private theorem ambient_to_model {C : Set Plane} (hC : IsJordanCurve C) :
    ∃ H : Plane ≃ₜ Plane, H '' C = modelCurve ∧
      H '' (C ∪ inside C) = Plane.closedSquare 0 1

private theorem scaled_square_interior {x : Plane} {t : ℝ}
    (hx : x∈Plane.closedSquare 0 1) (ht : 0≤t) (ht1 : t<1) :
    t • x ∈ Plane.openSquare 0 1
